 1  import { FocusEvent } from 'react';
 2  import { InputBaseComponentProps } from '@mui/material';
 3  
 4  // "90m", "1.5h" or "1h30" -> "1h 30m"; anything else is left as typed.
 5  export function normaliseDuration(text: string): string {
 6    const trimmed = text.trim().toLowerCase();
 7    const hours = trimmed.match(/^(\d+(?:\.\d+)?)\s*h$/);
 8    const minutes = trimmed.match(/^(\d+)\s*m$/);
 9    const both = trimmed.match(/^(\d+)\s*h\s*(\d+)\s*m?$/);
10    let total: number | null = null;
11    if (hours) total = Math.round(Number(hours[1]) * 60);
12    else if (minutes) total = Number(minutes[1]);
13    else if (both) total = Number(both[1]) * 60 + Number(both[2]);
14    if (total === null) return text;
15    const h = Math.floor(total / 60);
16    const m = total % 60;
17    return [h ? `${h}h` : '', m ? `${m}m` : ''].filter(Boolean).join(' ') || '0m';
18  }
19  
20  // An input that tidies the duration when the user leaves the field.
21  export function DurationInput(props: InputBaseComponentProps) {
22    const { inputRef, onBlur, ...other } = props;
23    return (
24      <input
25        {...other}
26        ref={inputRef}
27        onBlur={(event: FocusEvent<HTMLInputElement>) => {
28          event.target.value = normaliseDuration(event.target.value);
29          onBlur?.(event);
30        }}
31      />
32    );
33  }

